from amazon.textract.client import TextractClient

client = TextractClient(aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'), aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'))

def extract_invoice_fields(invoice_image):
    response = client.analyze_document(Document={'Bytes': invoice_image}, FeatureTypes=['FORMS', 'TABLES'])
    extracted_data = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = block['Text'].strip()
            value = next((b['Text'] for b in response['Blocks'] if b['Id'] == block['Relationships'][0]['Ids'][0]), None)
            if key in ['Vendor', 'Date', 'Total']:
                extracted_data[key] = value
    return extracted_data",
